import shutil
import subprocess
from pathlib import Path

from core import BIN_DIR, STOW_DIR, detect_os, run, which

HOME = Path.home()
MISE_BIN = BIN_DIR / "mise"
DEFAULT_GEMS_FILE = HOME / ".default-gems"

# Machine-local LazyVim spec (gitignored). lua/config/lazy.lua imports it only
# when the directory exists, so machines without Ruby are unaffected.
NVIM_EXTRAS_DIR = STOW_DIR / "lazyvim" / ".config" / "nvim" / "lua" / "extras-local"
NVIM_EXTRAS_FILE = NVIM_EXTRAS_DIR / "ruby.lua"

NVIM_RUBY_SPEC = """\
-- Generated by the dotfiles installer (tools_management/ruby_setup.py).
-- Machine-local and gitignored: delete it or set ruby.enabled = false to opt out.
-- Ruby tooling is resolved from PATH (mise), not Mason, so it follows the
-- Ruby version active in the current directory.
return {
  { import = "lazyvim.plugins.extras.lang.ruby" },
  {
    "neovim/nvim-lspconfig",
    opts = {
      servers = {
        ruby_lsp = { mason = false },
        -- ruby-lsp already runs the project's RuboCop; a second server duplicates diagnostics.
        rubocop = { enabled = false },
      },
    },
  },
  {
    "stevearc/conform.nvim",
    optional = true,
    opts = function(_, opts)
      opts.formatters_by_ft = opts.formatters_by_ft or {}
      -- If the project bundles RuboCop, ruby-lsp formats with that version and its plugins
      -- (an empty list falls back to LSP formatting). Otherwise use the RuboCop on PATH (mise).
      opts.formatters_by_ft.ruby = function(bufnr)
        local lock = vim.fs.find("Gemfile.lock", { upward = true, path = vim.api.nvim_buf_get_name(bufnr) })[1]
        if lock then
          for line in io.lines(lock) do
            if line:match("^    rubocop %(") then
              return {}
            end
          end
        end
        return { "rubocop" }
      end
      return opts
    end,
  },
  {
    "mason-org/mason.nvim",
    opts = function(_, opts)
      -- Mason's gem packages break when the Ruby version changes; erb-format comes from default gems.
      opts.ensure_installed = vim.tbl_filter(function(tool)
        return tool ~= "erb-formatter" and tool ~= "erb-lint"
      end, opts.ensure_installed or {})
      return opts
    end,
  },
  {
    "nvim-treesitter/nvim-treesitter",
    opts = { ensure_installed = { "embedded_template" } },
  },
}
"""


def ruby_config(config: dict) -> dict:
    return config.get("ruby", {})


def ruby_enabled(config: dict) -> bool:
    return bool(ruby_config(config).get("enabled", False))


def ruby_system_packages(config: dict) -> list[str]:
    """Native build dependencies for the current OS, or [] when Ruby is off."""
    if not ruby_enabled(config):
        return []
    pkgs = ruby_config(config).get("system_packages", {})
    return list(pkgs.get("brew" if detect_os() == "macos" else "apt", []))


def _mise() -> str:
    return shutil.which("mise") or str(MISE_BIN)


def install_mise() -> None:
    if which("mise"):
        print("✅ mise already installed")
        return
    print("📋 Installing mise...")
    run(["bash", "-c", "curl -fsSL https://mise.run | sh"])


def _ensure_default_gems(gems: list[str]) -> None:
    """mise installs every gem listed here after each `mise install ruby@...`."""
    existing = (
        DEFAULT_GEMS_FILE.read_text().splitlines() if DEFAULT_GEMS_FILE.is_file() else []
    )
    present = {line.split()[0] for line in existing if line.strip() and not line.startswith("#")}
    missing = [g for g in gems if g not in present]
    if not missing:
        return
    DEFAULT_GEMS_FILE.write_text("\n".join([*existing, *missing]) + "\n")
    print(f"   ✓ ~/.default-gems: added {', '.join(missing)}")


def generate_nvim_extras() -> None:
    NVIM_EXTRAS_DIR.mkdir(parents=True, exist_ok=True)
    NVIM_EXTRAS_FILE.write_text(NVIM_RUBY_SPEC)
    print("   ✓ lazyvim: generated lua/extras-local/ruby.lua")


def install_ruby(config: dict) -> None:
    rb = ruby_config(config)
    version = rb.get("version", "latest")
    gems = rb.get("gems", [])
    mise = _mise()

    print(f"📋 Setting up Ruby {version} via mise...")
    _ensure_default_gems(gems)
    run([mise, "install", f"ruby@{version}"])
    run([mise, "use", "--global", f"ruby@{version}"])
    if gems:
        # Covers a Ruby that was already installed before the gem list changed.
        run([mise, "exec", f"ruby@{version}", "--", "gem", "install", "--conservative", "--no-document", *gems])
    generate_nvim_extras()


def ruby_status(config: dict) -> bool:
    version = ruby_config(config).get("version", "latest")
    try:
        result = subprocess.run(
            [_mise(), "where", f"ruby@{version}"], capture_output=True
        )
    except FileNotFoundError:
        return False
    return result.returncode == 0


def uninstall_mise() -> None:
    if MISE_BIN.is_symlink() or MISE_BIN.exists():
        MISE_BIN.unlink()
        print("   removed ~/.local/bin/mise")
    for path in (
        HOME / ".local" / "share" / "mise",
        HOME / ".cache" / "mise",
        HOME / ".config" / "mise",
    ):
        if path.is_dir():
            shutil.rmtree(path)
            print(f"   removed {path}")


def uninstall_ruby() -> None:
    if NVIM_EXTRAS_DIR.is_dir():
        shutil.rmtree(NVIM_EXTRAS_DIR)
        print("   removed lazyvim lua/extras-local")
    # ~/.default-gems is kept on purpose: it may hold gems the user added.
